import type { HTMLAttributes, ReactNode } from "react";
import { cx } from "../utils/cx";

export type ToolbarProps = HTMLAttributes<HTMLDivElement> & {
  /** Names the toolbar for assistive technology. */
  "aria-label": string;
  /** Content pushed to the far end (a count, a button). */
  end?: ReactNode;
};

/**
 * A filter bar: a search field, selects and toggles in one wrapping row, with an optional trailing slot. Put the
 * controls in as children (`Input`, `Select`, `SegmentedControl`, `Button`).
 */
export function Toolbar({ end, className, children, ...rest }: ToolbarProps) {
  return (
    <div role="toolbar" {...rest} className={cx("hm-toolbar", className)}>
      <div className="hm-toolbar-main">{children}</div>
      {end ? <div className="hm-toolbar-end">{end}</div> : null}
    </div>
  );
}

export type SettingsSectionProps = Omit<HTMLAttributes<HTMLElement>, "title"> & {
  title: ReactNode;
  description?: ReactNode;
  /** The heading element of the title (`2` to `6`), so it follows the page's outline. Default 2. */
  level?: 2 | 3 | 4 | 5 | 6;
};

/** A titled group of settings rows, divided by hairlines. */
export function SettingsSection({ title, description, level = 2, className, children, ...rest }: SettingsSectionProps) {
  const Heading = `h${level}` as "h2";
  return (
    <section {...rest} className={cx("hm-settings", className)}>
      <header className="hm-settings-head">
        <Heading className="hm-settings-title">{title}</Heading>
        {description ? <p className="hm-settings-description">{description}</p> : null}
      </header>
      <div className="hm-settings-rows">{children}</div>
    </section>
  );
}

export type SettingsRowProps = Omit<HTMLAttributes<HTMLDivElement>, "title"> & {
  title: ReactNode;
  description?: ReactNode;
  /** The control (a switch, select, button) at the end of the row. */
  control: ReactNode;
};

/** One setting: its name and explanation on the left, the control on the right (stacked on phones). */
export function SettingsRow({ title, description, control, className, ...rest }: SettingsRowProps) {
  return (
    <div {...rest} className={cx("hm-settings-row", className)}>
      <div className="hm-settings-text">
        <p className="hm-settings-name">{title}</p>
        {description ? <p className="hm-settings-hint">{description}</p> : null}
      </div>
      <div className="hm-settings-control">{control}</div>
    </div>
  );
}
